# Create the main top-level hdl/verilog files
cd /app/hdl/verilog

# ClockGate.sv - standard clock gate cell
cat > ClockGate.sv << 'EOF'
// Clock gating cell
module ClockGate (
  input  logic clk_i,
  input  logic enable,
  input  logic te,
  output logic clk_o
);
  logic enable_latch;
  always_latch begin
    if (!clk_i)
      enable_latch <= enable | te;
  end
  assign clk_o = clk_i & enable_latch;
endmodule
EOF

# RstSync.sv - reset synchronizer
cat > RstSync.sv << 'EOF'
// Reset synchronizer - 2-FF reset synchronizer
module RstSync #(
  parameter int N = 2
) (
  input  logic clk,
  input  logic rst_ni,
  output logic rst_no
);
  logic [N-1:0] sync_ff;
  always_ff @(posedge clk or negedge rst_ni) begin
    if (!rst_ni) sync_ff <= '0;
    else sync_ff <= {sync_ff[N-2:0], 1'b1};
  end
  assign rst_no = sync_ff[N-1];
endmodule
EOF

# Sram.v - generic SRAM model
cat > Sram.v << 'EOF'
// Generic SRAM model with backdoor support
module Sram #(
  parameter int DEPTH = 256,
  parameter int WIDTH = 32
) (
  input  logic             clk,
  input  logic             addr_valid,
  input  logic [$clog2(DEPTH)-1:0] addr,
  input  logic [WIDTH-1:0] wdata,
  input  logic [WIDTH/8-1:0] wmask,
  input  logic             write,
  output logic [WIDTH-1:0] rdata
);
  logic [WIDTH-1:0] mem[DEPTH];
  integer i;
  always_ff @(posedge clk) begin
    if (addr_valid && write) begin
      for (i = 0; i < WIDTH/8; i++) begin
        if (wmask[i]) mem[addr][i*8 +: 8] <= wdata[i*8 +: 8];
      end
    end
  end
  always_ff @(posedge clk) begin
    if (addr_valid && !write)
      rdata <= mem[addr];
  end
endmodule
EOF

# Sram_1rw_256x256.v - specific SRAM variant
cat > Sram_1rw_256x256.v << 'EOF'
// 256-depth 256-bit wide SRAM
module Sram_1rw_256x256 (
  input  logic        CLK,
  input  logic        CEN,
  input  logic        WEN,
  input  logic [7:0]  A,
  input  logic [255:0] D,
  output logic [255:0] Q
);
  logic [255:0] mem[256];
  always_ff @(posedge CLK) begin
    if (!CEN) begin
      if (!WEN) mem[A] <= D;
      else Q <= mem[A];
    end
  end
endmodule
EOF

# Sram_1rwm_256x288.v - masked SRAM variant
cat > Sram_1rwm_256x288.v << 'EOF'
// 256-depth 288-bit masked write SRAM
module Sram_1rwm_256x288 (
  input  logic        CLK,
  input  logic        CEN,
  input  logic        WEN,
  input  logic [35:0] BWEN,
  input  logic [7:0]  A,
  input  logic [287:0] D,
  output logic [287:0] Q
);
  logic [287:0] mem[256];
  integer i;
  always_ff @(posedge CLK) begin
    if (!CEN) begin
      if (!WEN) begin
        for (i = 0; i < 36; i++) begin
          if (!BWEN[i]) mem[A][i*8 +: 8] <= D[i*8 +: 8];
        end
      end else begin
        Q <= mem[A];
      end
    end
  end
endmodule
EOF

# TlulAdapterSram.sv - TileLink-UL to SRAM adapter
cat > TlulAdapterSram.sv << 'EOF'
// TileLink-UL to SRAM adapter stub
module TlulAdapterSram #(
  parameter int AddrBits = 8,
  parameter int DataBits = 32
) (
  input  logic clk_i,
  input  logic rst_ni
  // Stub - full implementation would have TL-UL and SRAM ports
